-- mod-advanced-professions: именные сочетания на всю сетку.
--
-- ФАЙЛ СОБРАН ГЕНЕРАТОРОМ `tools/gen-synergies.py` - правится он, а не эта
-- миграция: руками здесь только те строки, которые владелец добавит поверх.
--
-- Эскизов: 2221 на 370 ступеней, из них 6 - «через
-- ступень» (редкий материал в наборе поднимает качество исхода), и 1866
-- призов заведено СВОИМИ КОПИЯМИ в блоке 175000-179999.
-- Ступеней без подходящих камней: 0. Ступеней, разобравших все свои
-- призы до последнего: 0.
--
-- РЕШЕНИЯ ВЛАДЕЛЬЦА, из которых это выросло:
--
-- * эскизов у ступени - СКОЛЬКО НАЙДЁТСЯ: ступень забирает все призы своего
--   рода, качества и уровня. Прежний счёт («один плюс по одному на каждые 25
--   уровней, не больше четырёх») оставлял семь сотен подходящих вещей лежать
--   без дела, а низкие полосы всё равно бедны призами и получают один-два
--   эскиза сами собой;
-- * приз - ТОГО ЖЕ КАЧЕСТВА, что основа. Синяя основа даёт синий именной
--   предмет. Исключение - редкий материал: камень качеством выше самой вещи
--   попадает в неё только через своё окно и поднимает исход на ступень. Это
--   именно исключение: эскиз через ступень живёт на НИЖНЕЙ основе, где на одно
--   гнездо меньше, поэтому таких эскизов один на каждую пятую ступень - девять
--   именных вещей из десяти собираются на своей ступени, из полного набора;
-- * ПОРЯДОК ВСТАВОК ЗНАЧИМ у всех: «малахит, цитрин» и обратный порядок -
--   разные эскизы (§2.6).
--
-- Приз - существующий предмет игры, а не новая строка (§2.6): у него своя
-- модель, статы и умения, чего сложением камней не выразить. Генератор их не
-- выдумывает, а подбирает: тот же род, тот же уровень (в пределах десяти),
-- нужное качество - и каждый предмет достаётся ровно одному эскизу.
--
-- Повторный прогон сносит прошлый результат ЦЕЛИКОМ - все эскизы ковочных
-- основ, вместе с привязкой к книгам. Раньше сносились только эскизы без книги,
-- и после v40 (книга у каждого эскиза) повторный прогон не заменял старое, а
-- удваивал его. Осиротевшие книги подберёт `gen-synergy-books.py`: он их
-- сносит и выдаёт заново, поэтому порядок прогона - сначала этот генератор,
-- потом книги.
--
-- Эскизы геройских заготовок (у них рецепт добывается, а не куётся) не
-- трогаются вовсе - они живут своим генератором.
--
-- Дизайн: .claude/advanced-professions/DESIGN.md §5.6, §2.6.

DELETE s FROM `ap_synergy` s
JOIN `ap_recipe` r ON r.`id` = s.`recipe_id`
WHERE r.`acquire` = 'forge';

-- И эскизы-сироты: рецепта, на котором они висели, уже нет. Появляются, когда
-- рецепты пересобирают (сетка) - строка эскиза рецепту не принадлежит и сама
-- за ним не уходит.
DELETE s FROM `ap_synergy` s
WHERE NOT EXISTS (SELECT 1 FROM `ap_recipe` r WHERE r.`id` = s.`recipe_id`);


-- --------------------------------------------------------------------------
-- 0. Свои копии призов
-- --------------------------------------------------------------------------
-- РЕШЕНИЕ ВЛАДЕЛЬЦА (2026-09-15): «изменим предметы, чтобы соответствовали
-- уровню, на который они перемещены; задания не трогая».
--
-- Ванильных вещей, годных в призы, не хватает. После запрета квестовых наград
-- (prizes.py) свободных на всю игру осталось 135, и лежат они не там, где
-- нужно: у бронзы, стали, саронита и титана свободных нет вовсе, а ступень без
-- призов получает один-два эскиза вместо выбора.
--
-- Поэтому недостающие призы заводятся КОПИЯМИ. Донором годится и квестовая
-- вещь: её оригинал остаётся у задания нетронутым - ни строка предмета, ни сам
-- квест не меняются. Копия получает свой номер в блоке 175000-179999, качество
-- своей ступени, уровень на две единицы выше основы и ПЕРЕСЧИТАННЫЕ числа.
--
-- ПЕРЕСЧЁТ - ОТ СВЕРСТНИКОВ, а не от уровня. Множитель считает генератор:
-- «насколько донор был сильнее средней вещи СВОЕЙ клетки, настолько же он
-- будет сильнее средней вещи новой». Так у копии сохраняется характер
-- оригинала - лёгкий кинжал остаётся лёгким, - и она не выпадает из полосы.
--
-- Что НЕ переезжает вместе с числами: чужие умения (`spellid_*`), привязка к
-- классу и расе, требование репутации и навыка, уникальность, ванильный набор
-- и стартовый квест. Копия - это вещь верстака, а не чужая награда: всё, чем
-- она была привязана к своему источнику, снимается.
DELETE t FROM `item_template` t
WHERE t.`entry` BETWEEN 175000 AND 179999
  AND NOT EXISTS (SELECT 1 FROM `ap_generated_item` g
                  WHERE g.`source_entry` = t.`entry`);

DELETE l FROM `item_template_locale` l
WHERE l.`ID` BETWEEN 175000 AND 179999;

DROP TEMPORARY TABLE IF EXISTS `ap_prize_plan`;
CREATE TEMPORARY TABLE `ap_prize_plan` (
  `entry`     INT UNSIGNED PRIMARY KEY,
  `donor`     INT UNSIGNED NOT NULL,
  `q`         TINYINT UNSIGNED NOT NULL,
  `ilvl`      SMALLINT UNSIGNED NOT NULL,
  `req_level` TINYINT UNSIGNED NOT NULL,
  `k_stat`    FLOAT NOT NULL,
  `k_dmg`     FLOAT NOT NULL,
  `k_armor`   FLOAT NOT NULL,
  `title`     VARCHAR(255) NOT NULL,
  KEY (`donor`)
);

