-- Копия строки донора целиком, а не перечисление полутора сотен колонок: так
-- она не разойдётся со схемой ядра (тот же приём, что у сетки основ, v32 §5).
DROP TEMPORARY TABLE IF EXISTS `ap_prize_copy`;
CREATE TEMPORARY TABLE `ap_prize_copy` AS
SELECT pp.`entry` AS `ap_entry`, pp.`q` AS `ap_q`, pp.`ilvl` AS `ap_ilvl`,
       pp.`req_level` AS `ap_req`, pp.`k_stat` AS `ap_ks`,
       pp.`k_dmg` AS `ap_kd`, pp.`k_armor` AS `ap_ka`, it.*
FROM `ap_prize_plan` pp
JOIN `item_template` it ON it.`entry` = pp.`donor`;

UPDATE `ap_prize_copy` c
SET c.`entry`        = c.`ap_entry`,
    c.`Quality`      = c.`ap_q`,
    c.`ItemLevel`    = c.`ap_ilvl`,
    c.`RequiredLevel` = c.`ap_req`,
    -- Всё, чем вещь была привязана к своему прежнему источнику.
    c.`bonding`      = 1,
    c.`startquest`   = 0,
    c.`ScriptName`   = '',
    c.`spellid_1` = 0, c.`spellid_2` = 0, c.`spellid_3` = 0,
    c.`spellid_4` = 0, c.`spellid_5` = 0,
    c.`AllowableClass` = -1,
    c.`AllowableRace`  = -1,
    c.`RequiredSkill` = 0, c.`RequiredSkillRank` = 0,
    c.`RequiredReputationFaction` = 0, c.`RequiredReputationRank` = 0,
    c.`maxcount` = 0, c.`itemset` = 0,
    c.`requiredhonorrank` = 0, c.`RequiredCityRank` = 0,
    c.`requiredspell` = 0, c.`RequiredDisenchantSkill` = -1,
    c.`RandomProperty` = 0, c.`RandomSuffix` = 0,
    -- Числа под новую клетку.
    c.`stat_value1` = ROUND(c.`stat_value1` * c.`ap_ks`),
    c.`stat_value2` = ROUND(c.`stat_value2` * c.`ap_ks`),
    c.`stat_value3` = ROUND(c.`stat_value3` * c.`ap_ks`),
    c.`stat_value4` = ROUND(c.`stat_value4` * c.`ap_ks`),
    c.`stat_value5` = ROUND(c.`stat_value5` * c.`ap_ks`),
    c.`stat_value6` = ROUND(c.`stat_value6` * c.`ap_ks`),
    c.`stat_value7` = ROUND(c.`stat_value7` * c.`ap_ks`),
    c.`stat_value8` = ROUND(c.`stat_value8` * c.`ap_ks`),
    c.`stat_value9` = ROUND(c.`stat_value9` * c.`ap_ks`),
    c.`stat_value10` = ROUND(c.`stat_value10` * c.`ap_ks`),
    c.`dmg_min1` = ROUND(c.`dmg_min1` * c.`ap_kd`),
    c.`dmg_max1` = ROUND(c.`dmg_max1` * c.`ap_kd`),
    c.`dmg_min2` = ROUND(c.`dmg_min2` * c.`ap_kd`),
    c.`dmg_max2` = ROUND(c.`dmg_max2` * c.`ap_kd`),
    c.`armor`    = ROUND(c.`armor` * c.`ap_ka`),
    c.`BuyPrice`  = ROUND(c.`BuyPrice` * c.`ap_kd`),
    c.`SellPrice` = ROUND(c.`SellPrice` * c.`ap_kd`);

ALTER TABLE `ap_prize_copy`
  DROP COLUMN `ap_entry`, DROP COLUMN `ap_q`, DROP COLUMN `ap_ilvl`,
  DROP COLUMN `ap_req`, DROP COLUMN `ap_ks`, DROP COLUMN `ap_kd`,
  DROP COLUMN `ap_ka`;

INSERT IGNORE INTO `item_template` SELECT * FROM `ap_prize_copy`;

-- Русское имя копии - имя оригинала с уровнем в скобках: игра сама так
-- различает одно имя на разных полосах («Клинок разведчика» стоит на 23, 33,
-- 43, 53 и 63). Имя собирает генератор и кладёт в `ap_synergy`; здесь оно
-- переносится в локаль, чтобы вещь звалась так же в сумке и в подсказке.
INSERT INTO `item_template_locale` (`ID`, `locale`, `Name`, `Description`)
SELECT pp.`entry`, 'ruRU', pp.`title`, COALESCE(dl.`Description`, '')
FROM `ap_prize_plan` pp
LEFT JOIN `item_template_locale` dl ON dl.`ID` = pp.`donor`
                                   AND dl.`locale` = 'ruRU'
ON DUPLICATE KEY UPDATE `Name` = VALUES(`Name`);

-- Имя в самой строке предмета - ТО ЖЕ, что и в локали. Свои вещи модуля так и
-- заведены (основы зовутся «Медный клинок» прямо в `item_template.name`), а
-- собранное отдельно по-английски разъезжалось: у трёх копий выходило одно имя
-- на двоих, потому что уровень и донор совпали, а номер сюда не доезжал.
UPDATE `item_template` t
JOIN `ap_prize_plan` pp ON pp.`entry` = t.`entry`
SET t.`name` = pp.`title`;

DROP TEMPORARY TABLE IF EXISTS `ap_prize_plan`;
DROP TEMPORARY TABLE IF EXISTS `ap_prize_copy`;

